SELECT public.industry_ingest_corpus(
  '[{"id":"fed_osha_fall_protection","knowledgeType":"federal_regulation","title":"OSHA Fall Protection (29 CFR 1926 Subpart M)","statement":"OSHA requires fall protection for construction workers at elevations of 6 feet or more above a lower level. Employers must provide guardrails, safety nets, or personal fall arrest systems.","interpretation":"Restoration work on roofs, attics, and elevated structures triggers fall protection requirements. Non-compliance can result in OSHA citations and liability exposure. Document compliance in the job file.","sourceClassification":"REGULATORY","sourceId":"osha-construction","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["osha","safety","fall_protection","construction","regulation"],"verificationStatus":"official"},{"id":"fed_osha_hazard_communication","knowledgeType":"federal_regulation","title":"OSHA Hazard Communication Standard (29 CFR 1910.1200)","statement":"OSHA requires employers to inform and train employees about chemical hazards in the workplace. Safety Data Sheets (SDS) must be available for all hazardous chemicals used on the job site.","interpretation":"Restoration projects frequently involve chemicals (cleaning agents, adhesives, coatings). Maintain SDS documentation and ensure crew training records are current.","sourceClassification":"REGULATORY","sourceId":"osha-construction","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["osha","safety","hazcom","chemicals","training"],"verificationStatus":"official"},{"id":"fed_osha_respiratory_protection","knowledgeType":"federal_regulation","title":"OSHA Respiratory Protection (29 CFR 1910.134)","statement":"OSHA requires respiratory protection when employees are exposed to airborne contaminants above permissible exposure limits, including during mold remediation, asbestos abatement, and dust-generating construction work.","interpretation":"Mold remediation and demolition work during restoration requires proper respiratory protection programs, fit testing, and medical evaluations. Document the respiratory protection program in the job file.","sourceClassification":"REGULATORY","sourceId":"osha-construction","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["osha","respiratory","mold","asbestos","safety"],"verificationStatus":"official"},{"id":"fed_epa_lead_rrp","knowledgeType":"federal_regulation","title":"EPA Lead Renovation, Repair & Painting Rule (40 CFR 745)","statement":"EPA requires that renovation, repair, and painting work in pre-1978 housing and child-occupied facilities be performed by certified lead-safe work practices. Certified renovators must be on site.","interpretation":"Nearly all residential insurance restoration in pre-1978 structures triggers the EPA Lead RRP Rule. Failure to follow lead-safe practices can result in EPA fines up to $37,500 per violation per day. Include lead testing in the inspection phase.","sourceClassification":"REGULATORY","sourceId":"epa-regulations","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["epa","lead","rrp","pre1978","renovation","regulation"],"verificationStatus":"official"},{"id":"fed_epa_asbestos","knowledgeType":"federal_regulation","title":"EPA Asbestos National Emission Standards (40 CFR 61 Subpart M)","statement":"EPA requires asbestos surveys before renovation or demolition of buildings that may contain asbestos-containing materials (ACM). Disturbance of ACM without proper controls is a federal violation.","interpretation":"Pre-1980 buildings commonly contain asbestos in insulation, floor tiles, and roofing materials. An asbestos survey should be ordered before destructive restoration work begins. Include survey results in the claim documentation.","sourceClassification":"REGULATORY","sourceId":"epa-regulations","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["epa","asbestos","survey","pre1980","abatement","regulation"],"verificationStatus":"official"},{"id":"fed_fema_flood_insurance","knowledgeType":"federal_regulation","title":"FEMA National Flood Insurance Program (NFIP)","statement":"The NFIP provides flood insurance to property owners in participating communities. Claims are adjusted by FEMA-authorized adjusters and follow specific documentation and proof-of-loss requirements.","interpretation":"Flood claims have unique requirements: proof of loss deadlines (typically 60 days), specific documentation of flood damage vs. non-flood damage, and elevation certificate requirements. Missing the proof-of-loss deadline can forfeit the claim.","sourceClassification":"REGULATORY","sourceId":"fema-flood-insurance","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["fema","flood","nfip","proof_of_loss","insurance"],"verificationStatus":"official"},{"id":"fed_osha_scaffolding","knowledgeType":"federal_regulation","title":"OSHA Scaffolding (29 CFR 1926 Subpart L)","statement":"OSHA requires scaffolds used in construction to be designed by a qualified person and erected under the supervision of a competent person. Scaffold capacity, access, fall protection, and inspection requirements apply.","interpretation":"Scaffolding during multi-story restoration work triggers specific OSHA requirements. Document scaffold inspections and competent person designation. Non-compliance creates both safety and liability exposure.","sourceClassification":"REGULATORY","sourceId":"osha-construction","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["osha","scaffolding","construction","safety","regulation"],"verificationStatus":"official"},{"id":"fed_osha_electrical_safety","knowledgeType":"federal_regulation","title":"OSHA Electrical Safety in Construction (29 CFR 1926 Subpart K)","statement":"OSHA requires safe electrical work practices during construction, including GFCI protection, proper wiring methods, and lockout/tagout procedures for de-energized equipment.","interpretation":"Water-damaged electrical systems present electrocution hazards during restoration. De-energize and lock out damaged electrical systems before water extraction and demolition. Document electrical safety measures.","sourceClassification":"REGULATORY","sourceId":"osha-construction","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["osha","electrical","safety","gfci","lockout","water_damage"],"verificationStatus":"official"},{"id":"wf_fnol_filing","knowledgeType":"workflow_stage","title":"FNOL Filing","statement":"First Notice of Loss initiates the claims process. The contractor or policyholder reports the loss to the carrier with date, cause, and initial damage description.","interpretation":"Timely FNOL filing is critical. Delays can jeopardize coverage. Include: date of loss, cause of loss, initial damage description, policy number, and contact information.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["fnol","intake","claims"],"stageOrder":1},{"id":"wf_initial_contact","knowledgeType":"workflow_stage","title":"Initial Policyholder Contact","statement":"The restoration contractor contacts the policyholder to assess urgency, schedule inspection, and set expectations for the claims process.","interpretation":"First contact sets the tone. Document the conversation, note the policyholder''s concerns, and provide a timeline for the next steps.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["contact","intake","customer_service"],"stageOrder":2},{"id":"wf_emergency_mitigation_dispatch","knowledgeType":"workflow_stage","title":"Emergency Mitigation Dispatch","statement":"For active water, fire, or storm damage, emergency mitigation crews are dispatched to stop further damage: water extraction, tarping, board-up, or smoke remediation.","interpretation":"Emergency mitigation is time-sensitive and typically covered by insurance. Document all actions taken, including timestamps, before-and-after photos, and equipment deployed.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["mitigation","emergency","water","fire","dispatch"],"stageOrder":3},{"id":"wf_site_inspection","knowledgeType":"workflow_stage","title":"Site Inspection & Damage Assessment","statement":"A thorough site inspection documents all visible and hidden damage. Includes photo documentation, moisture readings, scope measurements, and damage classification.","interpretation":"Inspection quality directly affects the estimate accuracy and supplement potential. Use date-stamped photos (wide and close-up), moisture meters, and detailed room-by-room documentation.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["inspection","assessment","photos","moisture"],"stageOrder":4},{"id":"wf_adjuster_meeting","knowledgeType":"workflow_stage","title":"Adjuster Inspection / Meeting","statement":"The carrier adjuster inspects the damage and develops their own estimate. The contractor should be present to point out all damage and provide supporting documentation.","interpretation":"Being present at the adjuster inspection is critical for accurate scoping. Prepare a damage summary, photo package, and initial scope before the meeting.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["adjuster","inspection","scoping"],"stageOrder":5},{"id":"wf_initial_estimate","knowledgeType":"workflow_stage","title":"Initial Estimate Preparation","statement":"The contractor prepares a Xactimate estimate based on the inspection findings, scope measurements, and applicable pricing for the area.","interpretation":"Estimate accuracy at this stage determines the baseline for the entire claim. Under-scoping creates supplement needs. Over-scoping creates adjuster pushback.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["estimate","xactimate","scoping","pricing"],"stageOrder":6},{"id":"wf_coverage_verification","knowledgeType":"workflow_stage","title":"Coverage Verification","statement":"Verify the policyholder''s insurance coverage, deductible, coverage limits, exclusions, and any special endorsements that may affect the claim.","interpretation":"Early coverage verification prevents wasted effort on uncovered items. Check for: coverage type (RCV vs ACV), deductible amount, wind/hail exclusions, flood exclusions, and code upgrade endorsements.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["coverage","policy","deductible","verification"],"stageOrder":7},{"id":"wf_authorization","knowledgeType":"workflow_stage","title":"Work Authorization","statement":"Obtain signed work authorization from the policyholder before beginning restoration. The authorization should scope the work, outline the payment structure, and define responsibilities.","interpretation":"Written authorization is essential. It protects both the contractor and policyholder. Always confirm authorization is on file before work begins.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["authorization","contract","legal","scope"],"stageOrder":8},{"id":"wf_mitigation_execution","knowledgeType":"workflow_stage","title":"Mitigation Execution","statement":"Execute the mitigation plan: water extraction, structural drying, dehumidification, content manipulation, antimicrobial treatment, and continuous moisture monitoring.","interpretation":"Mitigation documentation (drying logs, moisture readings, equipment placement photos) is among the most frequently disputed items. Maintain daily logs with timestamps.","sourceClassification":"ATLAS_CURATED","sourceId":"iicrc-standards","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["mitigation","drying","water","documentation"],"stageOrder":9},{"id":"wf_content_manipulation","knowledgeType":"workflow_stage","title":"Content Manipulation & Pack-Out","statement":"Affected contents are inventoried, packed, cleaned, stored, and returned. Non-salvageable contents are documented and disposed of with proper authorization.","interpretation":"Content inventory is a significant revenue and liability point. Photograph every item, maintain chain of custody, and get policyholder sign-off on disposals.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["content","packout","inventory","salvage"],"stageOrder":10},{"id":"wf_demolition","knowledgeType":"workflow_stage","title":"Selective Demolition","statement":"Remove damaged materials (drywall, flooring, cabinetry, insulation) to prepare for reconstruction. Document all demolition with before/during photos.","interpretation":"Demolition reveals hidden damage. Always document what is found behind removed materials — this often creates legitimate supplement opportunities.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["demolition","tearout","hidden_damage"],"stageOrder":11},{"id":"wf_permit_acquisition","knowledgeType":"workflow_stage","title":"Permit Acquisition","statement":"Obtain required building permits before reconstruction. Permit requirements vary by jurisdiction and scope of work.","interpretation":"Permits are required for structural work, electrical, plumbing, and HVAC changes. Permit costs are generally recoverable as part of the claim. Include permit fees in the estimate.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["permits","compliance","code","regulation"],"stageOrder":12},{"id":"wf_code_compliance_assessment","knowledgeType":"workflow_stage","title":"Code Compliance Assessment","statement":"Evaluate current building code requirements that may necessitate upgrades beyond the pre-loss condition. Common triggers include: ice and water shield, upgraded ventilation, and electrical code updates.","interpretation":"Code upgrades can represent legitimate supplement items. Document the applicable code requirement, the pre-loss condition, and the upgrade needed. Recovery depends on jurisdiction and carrier policy.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.75,"isInference":false,"status":"active","tags":["code","compliance","upgrade","regulation"],"stageOrder":13},{"id":"wf_material_procurement","knowledgeType":"workflow_stage","title":"Material Procurement & Pricing","statement":"Source and procure materials for reconstruction. Track material costs, delivery timelines, and any price variances from the original estimate.","interpretation":"Material price increases between estimate date and purchase date can create recoverable price variance. Document current pricing with invoices and receipts.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["materials","procurement","pricing","cost"],"stageOrder":14},{"id":"wf_reconstruction","knowledgeType":"workflow_stage","title":"Reconstruction","statement":"Execute the reconstruction scope: framing, roofing, drywall, painting, flooring, cabinetry, trim, and finishing. Manage subcontractors and maintain quality control.","interpretation":"During reconstruction, scope changes are common. Document every change order with policyholder authorization. Unrecorded changes are unrecovered revenue.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["reconstruction","building","subcontractors","quality"],"stageOrder":15},{"id":"wf_quality_inspection","knowledgeType":"workflow_stage","title":"Quality Inspection & Punch List","statement":"Perform quality inspection of completed work. Create a punch list of any deficiencies and complete corrections before final invoicing.","interpretation":"Quality issues discovered after final invoicing create costly callbacks. Complete the punch list before requesting final payment.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["quality","inspection","punch_list"],"stageOrder":16},{"id":"wf_final_documentation","knowledgeType":"workflow_stage","title":"Final Documentation Assembly","statement":"Compile the complete job documentation package: photos, invoices, permits, change orders, material receipts, inspection reports, and completion certificates.","interpretation":"A complete documentation package is the foundation for clean invoicing and dispute prevention. Assemble documentation before generating the final invoice.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["documentation","assembly","package"],"stageOrder":17},{"id":"wf_final_inspection","knowledgeType":"workflow_stage","title":"Final Inspection & Sign-Off","statement":"Policyholder and/or adjuster performs final inspection. Obtain signed completion acknowledgment.","interpretation":"Signed completion acknowledgment protects against later disputes about whether work was completed. Get both policyholder and adjuster signatures where possible.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["inspection","signoff","completion"],"stageOrder":18},{"id":"wf_supplement_identification","knowledgeType":"workflow_stage","title":"Supplement Opportunity Identification","statement":"Compare the original carrier estimate against the actual scope, code requirements, and discovered conditions to identify supplement opportunities.","interpretation":"Systematic comparison of estimate vs. actual scope is the foundation of revenue recovery. Document every gap with supporting evidence (photos, code references, invoices).","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["supplement","revenue","gap_analysis"],"stageOrder":19},{"id":"wf_supplement_documentation","knowledgeType":"workflow_stage","title":"Supplement Documentation Assembly","statement":"Build the supplement package: line-by-line comparison, photo evidence, code references, manufacturer specifications, and supporting documentation for each additional item.","interpretation":"Well-documented supplements with photo evidence and code references tend to have better approval outcomes. Each line item should have clear justification.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["supplement","documentation","evidence"],"stageOrder":20},{"id":"wf_supplement_submission","knowledgeType":"workflow_stage","title":"Supplement Submission to Adjuster","statement":"Submit the supplement package to the carrier adjuster with a cover letter explaining each additional item and the supporting evidence.","interpretation":"Professional supplement submission improves outcomes. Include a clear summary of the total supplement amount and the key supporting evidence for each category of additional work.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["supplement","submission","adjuster"],"stageOrder":21},{"id":"wf_supplement_negotiation","knowledgeType":"workflow_stage","title":"Supplement Negotiation & Follow-Up","statement":"The adjuster reviews the supplement and may approve, partially approve, or deny items. Follow up professionally with additional evidence as needed.","interpretation":"Supplement negotiation is iterative. Denied items may be recoverable with additional documentation. Track the status of each line item throughout the negotiation process.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["supplement","negotiation","followup"],"stageOrder":22},{"id":"wf_change_order_tracking","knowledgeType":"workflow_stage","title":"Change Order Documentation & Tracking","statement":"Document all scope changes during reconstruction with written change orders including the reason, cost impact, and policyholder authorization.","interpretation":"Change orders are a primary source of unrecovered revenue. Every scope change should be documented with a signed change order before the additional work proceeds.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["change_order","scope_change","revenue","documentation"],"stageOrder":23},{"id":"wf_code_upgrade_supplement","knowledgeType":"workflow_stage","title":"Code Upgrade Supplement Preparation","statement":"When building codes require upgrades beyond the pre-loss condition, prepare a code upgrade supplement with the applicable code section, jurisdiction requirements, and cost documentation.","interpretation":"Code upgrade supplements require specific code citations and jurisdiction verification. Recovery varies significantly by carrier and jurisdiction. Document the regulatory authority for each upgrade.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.75,"isInference":false,"status":"active","tags":["code_upgrade","supplement","regulation"],"stageOrder":24},{"id":"wf_estimate_reconciliation","knowledgeType":"workflow_stage","title":"Estimate vs. Actual Reconciliation","statement":"Compare the original estimate, approved supplements, and actual costs to identify any remaining revenue gaps or overages.","interpretation":"Systematic reconciliation catches unbilled work and overcharges. This should be performed before final invoicing to ensure all billable items are captured.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["reconciliation","estimate","actual","revenue"],"stageOrder":25},{"id":"wf_final_invoice","knowledgeType":"workflow_stage","title":"Final Invoice Preparation","statement":"Prepare the final invoice reflecting all approved work, supplements, change orders, and code upgrades. Include supporting documentation references.","interpretation":"The final invoice should reconcile against the approved estimate + supplements. Discrepancies at this stage create payment delays.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["invoice","billing","final","payment"],"stageOrder":26},{"id":"wf_payment_processing","knowledgeType":"workflow_stage","title":"Payment Processing & Reconciliation","statement":"Receive and reconcile carrier payments against the approved amounts. Identify any short-payments or deductions that require follow-up.","interpretation":"Short-payments are common and may require additional documentation or appeal. Track all payments against the approved amounts systematically.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["payment","reconciliation","shortpay"],"stageOrder":27},{"id":"wf_residual_recovery","knowledgeType":"workflow_stage","title":"Residual Revenue Recovery","statement":"After primary payment, identify any remaining recoverable revenue through additional supplements, appeal of denied items, or uncovered scope.","interpretation":"Residual recovery requires careful analysis of what was approved vs. what was submitted. Some denied items may be recoverable with additional evidence or appeal.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.7,"isInference":false,"status":"active","tags":["residual","recovery","appeal","revenue"],"stageOrder":28},{"id":"wf_job_closeout","knowledgeType":"workflow_stage","title":"Job Closeout & Archival","statement":"Complete final closeout: archive all documentation, close out subcontractor accounts, release retainage, and finalize the job file.","interpretation":"Complete archival of job documentation protects against future disputes and provides reference data for similar future claims.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["closeout","archive","documentation"],"stageOrder":29},{"id":"wf_customer_satisfaction","knowledgeType":"workflow_stage","title":"Customer Satisfaction & Warranty","statement":"Confirm policyholder satisfaction with completed work. Provide warranty documentation and maintenance guidance.","interpretation":"Post-completion follow-up builds referral relationships and reduces callback rates. Document the satisfaction confirmation in the job file.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.75,"isInference":false,"status":"active","tags":["satisfaction","warranty","customer"],"stageOrder":30},{"id":"wf_analytics_review","knowledgeType":"workflow_stage","title":"Claim Analytics & Lessons Learned","statement":"Review the completed claim for analytics: total revenue, recovery rate, supplement success rate, documentation completeness, and lessons learned.","interpretation":"Post-claim analytics improve future performance. Track metrics like supplement approval rate, revenue per claim, and documentation completeness scores.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.7,"isInference":true,"status":"active","tags":["analytics","metrics","lessons_learned"],"stageOrder":31},{"id":"doc_fnol_loss_report","knowledgeType":"documentation_evidence","title":"Loss Report / Claim Notice","statement":"The initial written report of loss to the carrier, including date of loss, cause, description of damage, policy information, and contact details.","interpretation":"The loss report initiates the claim timeline. Accuracy and completeness at this stage prevent downstream delays.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["fnol","loss_report","documentation"]},{"id":"doc_fnol_policy_info","knowledgeType":"documentation_evidence","title":"Policy Information Summary","statement":"Summary of insurance policy: coverage type (RCV/ACV), deductible, limits, exclusions, and relevant endorsements.","interpretation":"Policy information determines coverage scope. Obtain the declarations page and any relevant endorsements early in the process.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["policy","coverage","declarations","documentation"]},{"id":"doc_fnol_initial_photos","knowledgeType":"documentation_evidence","title":"Initial Damage Photos","statement":"Date-stamped photographs documenting the initial damage before any mitigation or restoration work begins.","interpretation":"Initial photos establish the baseline damage condition. Without them, disputes about pre-existing conditions become difficult to resolve.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["photos","initial","damage","documentation"]},{"id":"doc_fnol_date_of_loss","knowledgeType":"documentation_evidence","title":"Date of Loss Documentation","statement":"Documentation establishing the date when the damage occurred: weather reports, utility records, neighbor statements, or event timestamps.","interpretation":"Date of loss is critical for coverage determination. For weather events, correlate with official weather data for the location.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["date_of_loss","timeline","documentation"]},{"id":"doc_fnol_cause_of_loss","knowledgeType":"documentation_evidence","title":"Cause of Loss Statement","statement":"Written statement describing the cause of the loss (wind, water, fire, etc.) with supporting evidence.","interpretation":"Cause of loss determines which coverage applies. Misidentification of cause can result in claim denial.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["cause_of_loss","origin","documentation"]},{"id":"doc_inspection_photos","knowledgeType":"documentation_evidence","title":"Inspection Photo Package","statement":"Comprehensive photo documentation of all damage: wide-angle room shots, close-up damage details, and labeled room/area identifiers.","interpretation":"Inspection photos are the most commonly incomplete documentation item. Photos should be date-stamped, labeled by room/area, and show both context and detail.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["photos","inspection","documentation"]},{"id":"doc_inspection_moisture","knowledgeType":"documentation_evidence","title":"Moisture Mapping / Readings","statement":"Moisture meter readings documenting the extent of water damage, mapped to a floor plan or room diagram.","interpretation":"Moisture mapping quantifies the extent of water damage and guides the drying plan. Essential for water mitigation claims.","sourceClassification":"ATLAS_CURATED","sourceId":"iicrc-standards","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["moisture","water","mapping","inspection"]},{"id":"doc_inspection_adjuster_notes","knowledgeType":"documentation_evidence","title":"Adjuster Inspection Notes","statement":"Notes and observations from the carrier adjuster''s site inspection, including their damage assessment and initial scope.","interpretation":"Adjuster notes reveal the carrier''s perspective on the damage. Compare against your own inspection to identify gaps.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["adjuster","notes","inspection"]},{"id":"doc_inspection_scope","knowledgeType":"documentation_evidence","title":"Scope Measurements & Diagrams","statement":"Detailed measurements of affected areas including room dimensions, material quantities, and damage extent.","interpretation":"Accurate scope measurements are the foundation of the Xactimate estimate. Inaccurate measurements lead to estimate disputes.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["scope","measurements","diagrams"]},{"id":"doc_inspection_weather","knowledgeType":"documentation_evidence","title":"Weather Event Documentation","statement":"Official weather data correlating the loss date with the reported weather event: wind speed, precipitation, hail size, temperature.","interpretation":"Weather documentation supports the cause-of-loss determination for weather-related claims. Use official sources (NOAA, weather stations).","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["weather","event","NOAA","documentation"]},{"id":"doc_inspection_video","knowledgeType":"documentation_evidence","title":"Video Walkthrough Documentation","statement":"Video walkthrough of the damaged property providing context and continuity that photos alone may miss.","interpretation":"Video documentation is increasingly valuable for complex claims. It provides context that individual photos cannot convey.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.7,"isInference":true,"status":"active","tags":["video","walkthrough","documentation"]},{"id":"doc_estimate_xactimate","knowledgeType":"documentation_evidence","title":"Xactimate Estimate","statement":"The formal Xactimate estimate with line items, quantities, pricing, and total scope of work.","interpretation":"The Xactimate estimate is the primary financial document. Line-item accuracy directly affects revenue and supplement potential.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["xactimate","estimate","pricing","documentation"]},{"id":"doc_estimate_scope_of_work","knowledgeType":"documentation_evidence","title":"Written Scope of Work","statement":"Detailed written description of all work to be performed, materials to be used, and specifications to be followed.","interpretation":"The written scope supplements the Xactimate line items and provides context for complex or unusual work items.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["scope","work","specifications"]},{"id":"doc_estimate_material_specs","knowledgeType":"documentation_evidence","title":"Material Specifications","statement":"Specifications for materials to be used in the restoration: product names, ratings, performance standards, and manufacturer requirements.","interpretation":"Material specifications justify pricing and ensure quality. Manufacturer specs support code compliance and warranty requirements.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["materials","specifications","products"]},{"id":"doc_estimate_pricing_docs","knowledgeType":"documentation_evidence","title":"Pricing Documentation","statement":"Supporting documentation for pricing: current Xactimate pricing, local material costs, labor rates, and overhead/profit calculations.","interpretation":"Pricing documentation supports estimate accuracy and supplement justification. Current pricing data is essential for material price variance claims.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["pricing","costs","labor","materials"]},{"id":"doc_estimate_overhead_profit","knowledgeType":"documentation_evidence","title":"Overhead & Profit Documentation","statement":"Documentation supporting overhead and profit calculations including business overhead records and industry standard O&P rates.","interpretation":"O&P is typically 10% overhead + 10% profit on top of the sub cost. Some carriers require specific documentation to approve O&P.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.75,"isInference":false,"status":"active","tags":["overhead","profit","O&P","documentation"]},{"id":"doc_mitigation_drying_log","knowledgeType":"documentation_evidence","title":"Drying Log","statement":"Daily moisture readings with timestamps documenting the drying progress: target readings, actual readings, equipment used, and environmental conditions.","interpretation":"Drying logs are critical evidence for water mitigation claims. Without timestamped moisture readings, equipment days and dehumidification charges are difficult to justify.","sourceClassification":"ATLAS_CURATED","sourceId":"iicrc-standards","industry":"insurance restoration","jurisdiction":"United States","confidence":0.95,"isInference":false,"status":"active","tags":["drying","log","moisture","water","mitigation"]},{"id":"doc_mitigation_equipment_invoices","knowledgeType":"documentation_evidence","title":"Equipment Invoices & Placement Photos","statement":"Invoices for mitigation equipment (dehumidifiers, fans, air movers) with equipment placement photos showing setup.","interpretation":"Equipment documentation supports the daily equipment charges in the mitigation invoice. Photos prove the equipment was deployed as claimed.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["equipment","invoices","mitigation","placement"]},{"id":"doc_mitigation_authorization","knowledgeType":"documentation_evidence","title":"Mitigation Authorization","statement":"Written authorization from the policyholder or carrier to perform emergency mitigation work.","interpretation":"Mitigation authorization protects against payment disputes. Get authorization before work begins whenever possible.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["authorization","mitigation","approval"]},{"id":"doc_mitigation_photos","knowledgeType":"documentation_evidence","title":"Mitigation Before/During/After Photos","statement":"Photo documentation showing conditions before mitigation, during the mitigation process, and after completion.","interpretation":"Before/during/after photos are powerful evidence for the mitigation invoice and any subsequent disputes.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["photos","mitigation","before_after"]},{"id":"doc_mitigation_dehumidification","knowledgeType":"documentation_evidence","title":"Dehumidification Documentation","statement":"Documentation of dehumidification process: grain depression readings, water extraction volumes, and psychrometric data.","interpretation":"Dehumidification documentation supports the technical basis for the drying process and equipment charges.","sourceClassification":"ATLAS_CURATED","sourceId":"iicrc-standards","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["dehumidification","drying","psychrometric"]},{"id":"doc_mitigation_content_inventory","knowledgeType":"documentation_evidence","title":"Content Inventory & Manipulation Log","statement":"Inventory of all contents affected by the loss, including items moved, cleaned, stored, or disposed of.","interpretation":"Content manipulation is a significant cost center. Detailed inventory prevents disputes and supports content coverage claims.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["content","inventory","manipulation"]},{"id":"doc_recon_permits","knowledgeType":"documentation_evidence","title":"Building Permits","statement":"Copies of all building permits obtained for the reconstruction work, including approved plans and inspection records.","interpretation":"Permit documentation proves code compliance and supports permit fee recovery. Unpermitted work creates liability exposure.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["permits","code","compliance","reconstruction"]},{"id":"doc_recon_sub_invoices","knowledgeType":"documentation_evidence","title":"Subcontractor Invoices","statement":"Invoices from subcontractors for specialized work: plumbing, electrical, HVAC, roofing, flooring, etc.","interpretation":"Sub invoices support the reconstruction estimate and provide backup for carrier review. Keep copies of all sub invoices.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["subcontractor","invoices","reconstruction"]},{"id":"doc_recon_material_receipts","knowledgeType":"documentation_evidence","title":"Material Receipts","statement":"Receipts for all materials purchased for the reconstruction work.","interpretation":"Material receipts support cost documentation and may be needed for supplement justification or carrier audit.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["materials","receipts","documentation"]},{"id":"doc_recon_change_orders","knowledgeType":"documentation_evidence","title":"Signed Change Orders","statement":"Written change orders for any scope changes during reconstruction, signed by the policyholder.","interpretation":"Unrecorded change orders are unrecovered revenue. Every scope change should have a signed change order before work proceeds.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.9,"isInference":false,"status":"active","tags":["change_order","scope_change","documentation"]},{"id":"doc_recon_before_after","knowledgeType":"documentation_evidence","title":"Before & After Reconstruction Photos","statement":"Photo documentation of reconstruction progress: before, during, and after each phase of work.","interpretation":"Before/after photos demonstrate work quality and support the final invoice. They are also valuable for portfolio and referral purposes.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["photos","before_after","reconstruction"]},{"id":"doc_recon_inspection_reports","knowledgeType":"documentation_evidence","title":"Inspection & Compliance Reports","statement":"Reports from building inspections, code compliance checks, and quality assurance reviews during reconstruction.","interpretation":"Inspection reports prove code compliance and quality. Include framing, electrical, plumbing, and final building inspections.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["inspection","compliance","reports"]},{"id":"doc_supplement_line_comparison","knowledgeType":"documentation_evidence","title":"Estimate Line-by-Line Comparison","statement":"Side-by-side comparison of the carrier estimate vs. the contractor estimate, identifying every scope difference.","interpretation":"Line-by-line comparison is the foundation of a defensible supplement. Each difference must be documented and justified.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["supplement","comparison","estimate","gap"]},{"id":"doc_supplement_code_refs","knowledgeType":"documentation_evidence","title":"Code Reference Documentation","statement":"Copies of applicable building code sections, manufacturer installation requirements, and regulatory standards that support supplement items.","interpretation":"Code references provide objective justification for supplement items. Include the full code section text, not just the section number.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["code","regulation","supplement","justification"]},{"id":"doc_supplement_cover_letter","knowledgeType":"documentation_evidence","title":"Supplement Cover Letter","statement":"Professional cover letter summarizing the supplement submission: total amount, key categories, and reference to supporting documentation.","interpretation":"A clear, professional cover letter improves adjuster engagement and processing speed. Summarize the key categories of additional scope.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["supplement","cover_letter","submission"]},{"id":"doc_supplement_response_log","knowledgeType":"documentation_evidence","title":"Supplement Response & Follow-Up Log","statement":"Log tracking each supplement submission, adjuster response, follow-up actions, and final disposition of each line item.","interpretation":"Tracking supplement responses prevents lost items and ensures timely follow-up. Many supplements require multiple rounds of negotiation.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["supplement","tracking","followup"]},{"id":"doc_financial_final_invoice","knowledgeType":"documentation_evidence","title":"Final Invoice Package","statement":"Complete final invoice with all approved work, supplements, change orders, and supporting documentation references.","interpretation":"The final invoice package should be self-contained and audit-ready. Include references to all supporting documentation.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.85,"isInference":false,"status":"active","tags":["invoice","financial","final"]},{"id":"doc_financial_payment_records","knowledgeType":"documentation_evidence","title":"Payment Records & Reconciliation","statement":"Records of all payments received from the carrier, reconciled against approved amounts.","interpretation":"Payment reconciliation identifies short-payments that may require additional follow-up or appeal.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["payment","reconciliation","financial"]},{"id":"doc_financial_profit_loss","knowledgeType":"documentation_evidence","title":"Job Profitability Analysis","statement":"Post-job analysis comparing estimated vs. actual costs, revenue, and margin for the completed claim.","interpretation":"Job profitability analysis improves estimating accuracy and identifies systematic revenue leakage patterns.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.7,"isInference":true,"status":"active","tags":["profitability","analysis","financial"]},{"id":"doc_financial_warranty","knowledgeType":"documentation_evidence","title":"Warranty Documentation","statement":"Written warranty for completed work covering materials and workmanship for the specified warranty period.","interpretation":"Warranty documentation protects both the contractor and policyholder. Specify what is covered, the duration, and any exclusions.","sourceClassification":"ATLAS_CURATED","sourceId":"insurance-industry-practice","industry":"insurance restoration","jurisdiction":"United States","confidence":0.8,"isInference":false,"status":"active","tags":["warranty","guarantee","documentation"]},{"id":"jur_al","knowledgeType":"jurisdiction","title":"Alabama — Insurance Restoration Jurisdiction Profile","statemen